// Manual CLI argument parser for rumdl
#![allow(dead_code)]

use crate::embedded;

#[derive(Debug, Clone)]
pub enum Color {
    Auto,
    Always,
    Never,
}
impl Color {
    fn parse(s: &str) -> Result<Self, String> {
        match s {
            "auto" => Ok(Color::Auto),
            "always" => Ok(Color::Always),
            "never" => Ok(Color::Never),
            _ => Err(format!("invalid color: {}", s)),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct GlobalOpts {
    pub color: Option<String>,
    pub config: Option<String>,
    pub no_config: bool,
    pub isolated: bool,
}

#[derive(Debug)]
pub enum Command {
    Check(CheckArgs),
    Fmt(CheckArgs),
    Init(InitArgs),
    Rule(RuleArgs),
    Explain(ExplainArgs),
    Config(ConfigArgs),
    Server(ServerArgs),
    Schema(SchemaArgs),
    Import(ImportArgs),
    Vscode(VscodeArgs),
    Completions(CompletionsArgs),
    Clean(CleanArgs),
    Version(VersionArgs),
}

#[derive(Debug, Default)]
pub struct CheckArgs {
    pub global: GlobalOpts,
    pub paths: Vec<String>,
    pub fix: bool,
    pub diff: bool,
    pub check_only: bool,
    pub list_rules: bool,
    pub disable: Vec<String>,
    pub enable: Vec<String>,
    pub extend_enable: Vec<String>,
    pub extend_disable: Vec<String>,
    pub exclude: Vec<String>,
    pub no_exclude: bool,
    pub include: Vec<String>,
    pub respect_gitignore: Option<bool>,
    pub verbose: bool,
    pub profile: bool,
    pub statistics: bool,
    pub quiet: bool,
    pub output: Option<String>,
    pub output_format: Option<String>,
    pub show_full_path: bool,
    pub flavor: Option<String>,
    pub stdin: bool,
    pub stdin_filename: Option<String>,
    pub stderr: bool,
    pub silent: bool,
    pub watch: bool,
    pub force_exclude: bool,
    pub no_cache: bool,
    pub cache_dir: Option<String>,
    pub fail_on: Option<String>,
    pub is_fmt: bool,
}

#[derive(Debug, Default)]
pub struct InitArgs {
    pub global: GlobalOpts,
    pub pyproject: bool,
}

#[derive(Debug, Default)]
pub struct RuleArgs {
    pub global: GlobalOpts,
    pub rule: Option<String>,
    pub output_format: Option<String>,
    pub fixable: bool,
    pub category: Option<String>,
    pub explain: bool,
    pub list_categories: bool,
}

#[derive(Debug, Default)]
pub struct ExplainArgs {
    pub global: GlobalOpts,
    pub rule: String,
}

#[derive(Debug, Default)]
pub struct ConfigArgs {
    pub global: GlobalOpts,
    pub subcommand: Option<ConfigSub>,
    pub defaults: bool,
    pub no_defaults: bool,
    pub output: Option<String>,
}

#[derive(Debug)]
pub enum ConfigSub {
    Get(String),
    File,
}

#[derive(Debug, Default)]
pub struct ServerArgs {
    pub global: GlobalOpts,
    pub port: Option<u16>,
    pub stdio: bool,
    pub verbose: bool,
}

#[derive(Debug)]
pub enum SchemaSub {
    Generate,
    Check,
    Print,
}

#[derive(Debug)]
pub struct SchemaArgs {
    pub global: GlobalOpts,
    pub sub: SchemaSub,
}

#[derive(Debug, Default)]
pub struct ImportArgs {
    pub global: GlobalOpts,
    pub file: String,
    pub output: Option<String>,
    pub format: String,
    pub dry_run: bool,
}

#[derive(Debug, Default)]
pub struct VscodeArgs {
    pub global: GlobalOpts,
    pub force: bool,
    pub update: bool,
    pub status: bool,
}

#[derive(Debug, Default)]
pub struct CompletionsArgs {
    pub global: GlobalOpts,
    pub shell: Option<String>,
    pub list: bool,
}

#[derive(Debug, Default)]
pub struct CleanArgs {
    pub global: GlobalOpts,
}

#[derive(Debug, Default)]
pub struct VersionArgs {
    pub global: GlobalOpts,
}

pub enum ArgError {
    Help(String),
    Version,
    Usage(String),
}

pub struct Parsed {
    pub command: Command,
}

const USAGE_ROOT: &str = include_str!("help_root.txt");

fn usage_no_command() -> String {
    format!(
        "{}",
        "Usage: executable [OPTIONS] <COMMAND>\n\nFor more information, try '--help'."
    )
}

fn usage_subcmd(subname: &str) -> String {
    let subhelp = match subname {
        "check" => include_str!("help_check.txt"),
        "fmt" => include_str!("help_fmt.txt"),
        "init" => include_str!("help_init.txt"),
        "rule" => include_str!("help_rule.txt"),
        "explain" => include_str!("help_explain.txt"),
        "config" => include_str!("help_config.txt"),
        "server" => include_str!("help_server.txt"),
        "schema" => include_str!("help_schema.txt"),
        "import" => include_str!("help_import.txt"),
        "vscode" => include_str!("help_vscode.txt"),
        "completions" => include_str!("help_completions.txt"),
        "clean" => include_str!("help_clean.txt"),
        "version" => include_str!("help_version.txt"),
        _ => include_str!("help_root.txt"),
    };
    // First 4 lines: description + blank + Usage line + blank? We want Usage line.
    let mut result = String::new();
    for line in subhelp.lines() {
        if line.starts_with("Usage:") {
            result.push_str(line);
            result.push('\n');
            break;
        }
    }
    result.push_str("\nFor more information, try '--help'.");
    result
}

pub fn parse(argv: &[String]) -> Result<Parsed, ArgError> {
    // argv[0] = program, argv[1] = subcommand or global flag
    let mut i = 1;
    let mut global = GlobalOpts::default();
    // Parse global options before subcommand
    while i < argv.len() {
        let a = &argv[i];
        match a.as_str() {
            "-h" | "--help" => {
                return Err(ArgError::Help(include_str!("help_root.txt").to_string()));
            }
            "-V" | "--version" => {
                return Err(ArgError::Version);
            }
            "--color" => {
                i += 1;
                if i >= argv.len() {
                    return Err(ArgError::Usage(format!(
                        "error: a value is required for '--color <COLOR>' but none was supplied\n\n{}",
                        usage_no_command()
                    )));
                }
                global.color = Some(argv[i].clone());
            }
            s if s.starts_with("--color=") => {
                global.color = Some(s[8..].to_string());
            }
            "--config" => {
                i += 1;
                if i >= argv.len() {
                    return Err(ArgError::Usage(format!(
                        "error: a value is required for '--config <CONFIG>' but none was supplied\n\n{}",
                        usage_no_command()
                    )));
                }
                global.config = Some(argv[i].clone());
            }
            s if s.starts_with("--config=") => {
                global.config = Some(s[9..].to_string());
            }
            "--no-config" => global.no_config = true,
            "--isolated" => global.isolated = true,
            _ => break,
        }
        i += 1;
    }

    if i >= argv.len() {
        // No subcommand
        println!("{}", include_str!("help_root.txt"));
        return Err(ArgError::Usage(String::new()));
    }

    let subname = argv[i].clone();
    i += 1;
    let rest: Vec<String> = argv[i..].to_vec();

    match subname.as_str() {
        "check" => parse_check(global, &rest, false).map(|c| Parsed { command: Command::Check(c) }),
        "fmt" => parse_check(global, &rest, true).map(|c| Parsed { command: Command::Fmt(c) }),
        "init" => parse_init(global, &rest).map(|c| Parsed { command: Command::Init(c) }),
        "rule" => parse_rule(global, &rest).map(|c| Parsed { command: Command::Rule(c) }),
        "explain" => parse_explain(global, &rest).map(|c| Parsed { command: Command::Explain(c) }),
        "config" => parse_config(global, &rest).map(|c| Parsed { command: Command::Config(c) }),
        "server" => parse_server(global, &rest).map(|c| Parsed { command: Command::Server(c) }),
        "schema" => parse_schema(global, &rest).map(|c| Parsed { command: Command::Schema(c) }),
        "import" => parse_import(global, &rest).map(|c| Parsed { command: Command::Import(c) }),
        "vscode" => parse_vscode(global, &rest).map(|c| Parsed { command: Command::Vscode(c) }),
        "completions" => parse_completions(global, &rest).map(|c| Parsed { command: Command::Completions(c) }),
        "clean" => parse_clean(global, &rest).map(|c| Parsed { command: Command::Clean(c) }),
        "version" => parse_version(global, &rest).map(|c| Parsed { command: Command::Version(c) }),
        "help" => {
            if let Some(arg) = rest.first() {
                let help = match arg.as_str() {
                    "check" => include_str!("help_check.txt"),
                    "fmt" => include_str!("help_fmt.txt"),
                    "init" => include_str!("help_init.txt"),
                    "rule" => include_str!("help_rule.txt"),
                    "explain" => include_str!("help_explain.txt"),
                    "config" => include_str!("help_config.txt"),
                    "server" => include_str!("help_server.txt"),
                    "schema" => include_str!("help_schema.txt"),
                    "import" => include_str!("help_import.txt"),
                    "vscode" => include_str!("help_vscode.txt"),
                    "completions" => include_str!("help_completions.txt"),
                    "clean" => include_str!("help_clean.txt"),
                    "version" => include_str!("help_version.txt"),
                    _ => return Err(ArgError::Usage(format!(
                        "error: unrecognized subcommand '{}'\n\nUsage: executable [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.",
                        arg
                    ))),
                };
                Err(ArgError::Help(help.to_string()))
            } else {
                Err(ArgError::Help(include_str!("help_root.txt").to_string()))
            }
        }
        _ => Err(ArgError::Usage(format!(
            "error: unrecognized subcommand '{}'\n\nUsage: executable [OPTIONS] <COMMAND>\n\nFor more information, try '--help'.",
            subname
        ))),
    }
}

fn missing_value(opt: &str, subhelp: &str) -> ArgError {
    ArgError::Usage(format!(
        "error: a value is required for '{}' but none was supplied\n\n{}For more information, try '--help'.",
        opt, subhelp
    ))
}

fn unexpected_arg(arg: &str, subhelp: &str) -> ArgError {
    ArgError::Usage(format!(
        "error: unexpected argument '{}' found\n\n{}For more information, try '--help'.",
        arg, subhelp
    ))
}

fn extract_usage_line(help: &str) -> String {
    for line in help.lines() {
        if line.starts_with("Usage:") {
            return format!("{}\n\n", line);
        }
    }
    String::new()
}

fn parse_check(global: GlobalOpts, rest: &[String], is_fmt: bool) -> Result<CheckArgs, ArgError> {
    let help = if is_fmt {
        include_str!("help_fmt.txt")
    } else {
        include_str!("help_check.txt")
    };
    let usage = extract_usage_line(help);

    let mut a = CheckArgs::default();
    a.global = global;
    a.is_fmt = is_fmt;
    if is_fmt {
        a.fix = true;
    }

    let mut i = 0;
    let mut double_dash = false;
    while i < rest.len() {
        let arg = &rest[i];
        if double_dash {
            a.paths.push(arg.clone());
            i += 1;
            continue;
        }
        match arg.as_str() {
            "-h" | "--help" => return Err(ArgError::Help(help.to_string())),
            "--" => double_dash = true,
            "-f" | "--fix" => a.fix = true,
            "--diff" => a.diff = true,
            "--check" => a.check_only = true,
            "-l" | "--list-rules" => a.list_rules = true,
            "-v" | "--verbose" => a.verbose = true,
            "--profile" => a.profile = true,
            "--statistics" => a.statistics = true,
            "-q" | "--quiet" => a.quiet = true,
            "--show-full-path" => a.show_full_path = true,
            "--stdin" => a.stdin = true,
            "--stderr" => a.stderr = true,
            "-s" | "--silent" => a.silent = true,
            "-w" | "--watch" => a.watch = true,
            "--force-exclude" => a.force_exclude = true,
            "--no-cache" => a.no_cache = true,
            "--no-exclude" => a.no_exclude = true,
            "--no-config" => a.global.no_config = true,
            "--isolated" => a.global.isolated = true,
            "-d" | "--disable" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                split_csv_into(&rest[i], &mut a.disable);
            }
            "-e" | "--enable" | "--rules" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                split_csv_into(&rest[i], &mut a.enable);
            }
            "--extend-enable" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                split_csv_into(&rest[i], &mut a.extend_enable);
            }
            "--extend-disable" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                split_csv_into(&rest[i], &mut a.extend_disable);
            }
            "--exclude" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                split_csv_into(&rest[i], &mut a.exclude);
            }
            "--include" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                split_csv_into(&rest[i], &mut a.include);
            }
            "--respect-gitignore" => a.respect_gitignore = Some(true),
            "--color" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.global.color = Some(rest[i].clone());
            }
            "--config" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.global.config = Some(rest[i].clone());
            }
            "-o" | "--output" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.output = Some(rest[i].clone());
            }
            "--output-format" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.output_format = Some(rest[i].clone());
            }
            "--flavor" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.flavor = Some(rest[i].clone());
            }
            "--stdin-filename" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.stdin_filename = Some(rest[i].clone());
            }
            "--cache-dir" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.cache_dir = Some(rest[i].clone());
            }
            "--fail-on" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.fail_on = Some(rest[i].clone());
            }
            s if s.starts_with("--respect-gitignore=") => {
                let v = &s[20..];
                match v {
                    "true" => a.respect_gitignore = Some(true),
                    "false" => a.respect_gitignore = Some(false),
                    _ => return Err(ArgError::Usage(format!(
                        "error: invalid value '{}' for '--respect-gitignore' [possible values: true, false]\n\n{}For more information, try '--help'.",
                        v, usage
                    ))),
                }
            }
            s if s.starts_with("--") && s.contains('=') => {
                let (k, v) = s.split_once('=').unwrap();
                // re-dispatch as two-arg form
                let next = vec![k.to_string(), v.to_string()];
                let mut new_rest: Vec<String> = Vec::new();
                new_rest.extend(next);
                new_rest.extend(rest[i+1..].iter().cloned());
                let remaining_args = [&rest[..i], &new_rest[..]].concat();
                // recurse with fresh
                return parse_check(a.global, &remaining_args, is_fmt);
            }
            s if s.starts_with("-") && s != "-" => {
                return Err(unexpected_arg(s, &usage));
            }
            _ => a.paths.push(arg.clone()),
        }
        i += 1;
    }
    Ok(a)
}

fn split_csv_into(s: &str, out: &mut Vec<String>) {
    for part in s.split(',') {
        let t = part.trim();
        if !t.is_empty() {
            out.push(t.to_string());
        }
    }
}

fn parse_init(global: GlobalOpts, rest: &[String]) -> Result<InitArgs, ArgError> {
    let help = include_str!("help_init.txt");
    let usage = extract_usage_line(help);
    let mut a = InitArgs::default();
    a.global = global;
    let mut i = 0;
    while i < rest.len() {
        let arg = &rest[i];
        match arg.as_str() {
            "-h" | "--help" => return Err(ArgError::Help(help.to_string())),
            "--pyproject" => a.pyproject = true,
            "--color" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.global.color = Some(rest[i].clone());
            }
            "--config" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.global.config = Some(rest[i].clone());
            }
            "--no-config" => a.global.no_config = true,
            "--isolated" => a.global.isolated = true,
            _ => return Err(unexpected_arg(arg, &usage)),
        }
        i += 1;
    }
    Ok(a)
}

fn parse_rule(global: GlobalOpts, rest: &[String]) -> Result<RuleArgs, ArgError> {
    let help = include_str!("help_rule.txt");
    let usage = extract_usage_line(help);
    let mut a = RuleArgs::default();
    a.global = global;
    let mut i = 0;
    while i < rest.len() {
        let arg = &rest[i];
        match arg.as_str() {
            "-h" | "--help" => return Err(ArgError::Help(help.to_string())),
            "-o" | "--output-format" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.output_format = Some(rest[i].clone());
            }
            "-f" | "--fixable" => a.fixable = true,
            "-c" | "--category" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.category = Some(rest[i].clone());
            }
            "--explain" => a.explain = true,
            "--list-categories" => a.list_categories = true,
            "--color" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.global.color = Some(rest[i].clone());
