fn parse_explain(global: GlobalOpts, rest: &[String]) -> Result<ExplainArgs, ArgError> {
    let help = include_str!("help_explain.txt");
    let usage = extract_usage_line(help);
    let mut a = ExplainArgs::default();
    a.global = global;
    let mut got_rule = false;
    let mut i = 0;
    while i < rest.len() {
        let arg = &rest[i];
        match arg.as_str() {
            "-h" | "--help" => return Err(ArgError::Help(help.to_string())),
            "--color" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.global.color = Some(rest[i].clone());
            }
            "--config" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.global.config = Some(rest[i].clone());
            }
            "--no-config" => a.global.no_config = true,
            "--isolated" => a.global.isolated = true,
            s if s.starts_with("-") => return Err(unexpected_arg(s, &usage)),
            _ => {
                if got_rule { return Err(unexpected_arg(arg, &usage)); }
                a.rule = arg.clone();
                got_rule = true;
            }
        }
        i += 1;
    }
    if !got_rule {
        return Err(ArgError::Usage(format!(
            "error: the following required arguments were not provided:\n  <RULE>\n\n{}For more information, try '--help'.",
            usage
        )));
    }
    Ok(a)
}

fn parse_config(global: GlobalOpts, rest: &[String]) -> Result<ConfigArgs, ArgError> {
    let help = include_str!("help_config.txt");
    let usage = extract_usage_line(help);
    let mut a = ConfigArgs::default();
    a.global = global;
    let mut i = 0;
    while i < rest.len() {
        let arg = &rest[i];
        match arg.as_str() {
            "-h" | "--help" => return Err(ArgError::Help(help.to_string())),
            "--defaults" => a.defaults = true,
            "--no-defaults" => a.no_defaults = true,
            "--output" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.output = Some(rest[i].clone());
            }
            "--color" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.global.color = Some(rest[i].clone());
            }
            "--config" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                a.global.config = Some(rest[i].clone());
            }
            "--no-config" => a.global.no_config = true,
            "--isolated" => a.global.isolated = true,
            "get" => {
                i += 1;
                if i >= rest.len() {
                    return Err(ArgError::Usage(format!(
                        "error: the following required arguments were not provided:\n  <KEY>\n\n{}For more information, try '--help'.",
                        usage
                    )));
                }
                a.subcommand = Some(ConfigSub::Get(rest[i].clone()));
            }
            "file" => a.subcommand = Some(ConfigSub::File),
            s if s.starts_with("-") => return Err(unexpected_arg(s, &usage)),
            _ => return Err(unexpected_arg(arg, &usage)),
        }
        i += 1;
    }
    Ok(a)
}

