    let usage = extract_usage_line(help);
    let mut i = 0;
    let mut g = global;
    while i < rest.len() {
        let arg = &rest[i];
        match arg.as_str() {
            "-h" | "--help" => return Err(ArgError::Help(help.to_string())),
            "--color" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                g.color = Some(rest[i].clone());
            }
            "--config" => {
                i += 1;
                if i >= rest.len() { return Err(missing_value(arg, &usage)); }
                g.config = Some(rest[i].clone());
            }
            "--no-config" => g.no_config = true,
            "--isolated" => g.isolated = true,
            "generate" => return Ok(SchemaArgs { global: g, sub: SchemaSub::Generate }),
            "check" => return Ok(SchemaArgs { global: g, sub: SchemaSub::Check }),
