pub fn find_rule(id_or_name: &str) -> Option<&'static RuleInfo> {
    let s = id_or_name.to_uppercase();
    let sl = id_or_name.to_lowercase();
    // Match by code (MD001) or by name (heading-increment)
    // Also accept "md1" -> "MD001"
    RULES.iter().find(|r| {
        r.code.eq_ignore_ascii_case(id_or_name) || r.name == sl || {
            // Normalize "md1" -> "MD001"
            if let Some(digits) = s.strip_prefix("MD") {
                if let Ok(n) = digits.parse::<u32>() {
                    return format!("MD{:03}", n) == r.code;
                }
            }
            false
        }
    })
}

