pub fn dispatch(parsed: Parsed) -> ExitCode {
    match parsed.command {
        Command::Check(a) => cmd_check(a),
        Command::Fmt(a) => cmd_check(a),
        Command::Init(a) => cmd_init(a),
        Command::Rule(a) => cmd_rule(a),
