fn cmd_init(a: InitArgs) -> ExitCode {
    if a.pyproject {
        let path = Path::new("pyproject.toml");
        if path.exists() {
            print!("pyproject.toml already exists. Would you like to append rumdl configuration? [y/N]\n> ");
            io::stdout().flush().ok();
            let mut buf = String::new();
            io::stdin().read_line(&mut buf).ok();
            let t = buf.trim().to_lowercase();
            if t == "y" || t == "yes" {
                let mut existing = String::new();
                if let Ok(s) = fs::read_to_string(path) {
                    existing = s;
                }
                // Append blank line if needed, then the append template
                let mut new_content = existing;
                if !new_content.ends_with('\n') {
                    new_content.push('\n');
                }
                new_content.push('\n');
                new_content.push_str(embedded::PYPROJECT_APPEND);
                if let Err(e) = fs::write(path, new_content) {
                    eprintln!("Error writing pyproject.toml: {}", e);
                    return ExitCode::from(1);
                }
                println!("Added rumdl configuration to pyproject.toml");
            } else {
                println!("Aborted. No changes made to pyproject.toml");
            }
            return ExitCode::from(0);
        } else {
            if let Err(e) = fs::write(path, embedded::PYPROJECT_NEW) {
                eprintln!("Error writing pyproject.toml: {}", e);
                return ExitCode::from(1);
            }
            println!("Created pyproject.toml with rumdl configuration");
            return ExitCode::from(0);
        }
    }

    let path = Path::new(".rumdl.toml");
    if path.exists() {
        println!("Configuration file already exists: .rumdl.toml");
        return ExitCode::from(0);
    }
    if let Err(e) = fs::write(path, embedded::RUMDL_TOML_TEMPLATE) {
        eprintln!("Error: Failed to create configuration file: {}", e);
        return ExitCode::from(1);
    }
    println!("Created default configuration file: .rumdl.toml");
    println!();
    println!("Setup complete! You can now:");
    println!("  • Run rumdl check . to lint your Markdown files");
    println!("  • Open your editor to see real-time linting");
    ExitCode::from(0)
}

fn cmd_clean(_a: CleanArgs) -> ExitCode {
    let dir = Path::new(".rumdl_cache");
    if !dir.exists() {
        println!("Cache directory does not exist: .rumdl_cache");
        return ExitCode::from(0);
    }
    // Count files/size recursively
    let (count, size) = count_dir(dir).unwrap_or((0, 0));
    if let Err(e) = fs::remove_dir_all(dir) {
        eprintln!("Error: Failed to clear cache: {}", e);
        return ExitCode::from(1);
    }
    println!("Cleared cache: .rumdl_cache");
    println!("  Removed {} across {} files", human_size(size), count);
    ExitCode::from(0)
}

fn count_dir(p: &Path) -> io::Result<(u64, u64)> {
    let mut count = 0u64;
    let mut size = 0u64;
    if p.is_dir() {
        for entry in fs::read_dir(p)? {
            let e = entry?;
            let path = e.path();
            if path.is_dir() {
                let (c, s) = count_dir(&path)?;
                count += c;
                size += s;
            } else {
                count += 1;
                if let Ok(md) = fs::metadata(&path) {
                    size += md.len();
                }
            }
        }
    }
    Ok((count, size))
}

fn human_size(bytes: u64) -> String {
    const KB: u64 = 1024;
    const MB: u64 = 1024 * 1024;
    const GB: u64 = 1024 * 1024 * 1024;
    if bytes >= GB {
        format!("{:.2} GB", bytes as f64 / GB as f64)
    } else if bytes >= MB {
        format!("{:.2} MB", bytes as f64 / MB as f64)
    } else if bytes >= KB {
        format!("{:.2} KB", bytes as f64 / KB as f64)
    } else {
        format!("{} B", bytes)
    }
}

fn cmd_rule(a: RuleArgs) -> ExitCode {
    if a.list_categories {
        print!("{}", embedded::RULE_CATEGORIES);
        return ExitCode::from(0);
    }

    let fmt = a.output_format.as_deref().unwrap_or("text");

    if let Some(ref rule_id) = a.rule {
        // Show info about a specific rule
        let rule = match embedded::find_rule(rule_id) {
            Some(r) => r,
            None => {
                eprintln!("Error: Unknown rule: {}", rule_id);
                return ExitCode::from(1);
            }
        };
        match fmt {
            "json" => {
                println!("{}", format_rule_json(rule, a.explain));
            }
            "json-lines" => {
                println!("{}", format_rule_json_line(rule));
            }
            _ => {
                println!("{} - {}", rule.code, rule.summary);
                println!();
                println!("Name: {}", rule.name);
                println!("Category: {}", rule.category);
                println!("Fix: Fix is always available.");
                println!("Documentation: https://rumdl.dev/{}/", rule.code.to_lowercase());
            }
        }
        return ExitCode::from(0);
    }

    // List all rules
    match fmt {
        "json" => {
            if a.explain {
                print!("{}", embedded::RULES_JSON_EXPLAIN);
            } else {
                print!("{}", embedded::RULES_JSON);
            }
        }
        "json-lines" => {
            print!("{}", embedded::RULES_JSON_LINES);
        }
        _ => {
            print!("{}", embedded::RULES_TEXT);
        }
    }
    ExitCode::from(0)
}

fn format_rule_json(r: &embedded::RuleInfo, _explain: bool) -> String {
    format!(
        "{{\n  \"code\": \"{}\",\n  \"name\": \"{}\",\n  \"aliases\": [],\n  \"summary\": \"{}\",\n  \"category\": \"{}\",\n  \"fix\": \"Fix is always available.\",\n  \"fix_availability\": \"Always\",\n  \"url\": \"https://rumdl.dev/{}/\"\n}}",
        r.code, r.name, r.summary, r.category, r.code.to_lowercase()
    )
}

fn format_rule_json_line(r: &embedded::RuleInfo) -> String {
    format!(
        "{{\"code\":\"{}\",\"name\":\"{}\",\"aliases\":[],\"summary\":\"{}\",\"category\":\"{}\",\"fix\":\"Fix is always available.\",\"fix_availability\":\"Always\",\"url\":\"https://rumdl.dev/{}/\"}}",
