fn count_dir(p: &Path) -> io::Result<(u64, u64)> {
    let mut count = 0u64;
    let mut size = 0u64;
    if p.is_dir() {
        for entry in fs::read_dir(p)? {
            let e = entry?;
            let path = e.path();
            if path.is_dir() {
                let (c, s) = count_dir(&path)?;
                count += c;
                size += s;
            } else {
                count += 1;
                if let Ok(md) = fs::metadata(&path) {
                    size += md.len();
                }
            }
        }
    }
    Ok((count, size))
}

fn human_size(bytes: u64) -> String {
