fn cmd_check(a: CheckArgs) -> ExitCode {
    let start = std::time::Instant::now();

    // Collect markdown files to check
    let mut files: Vec<PathBuf> = Vec::new();

    if a.stdin {
        // Handle stdin specifically
        let mut buf = String::new();
        if let Err(e) = io::stdin().read_to_string(&mut buf) {
            eprintln!("Error reading stdin: {}", e);
            return ExitCode::from(1);
        }
        let fname = a.stdin_filename.clone().unwrap_or_else(|| "<stdin>".to_string());
        return run_stdin(&a, &fname, &buf, start);
    }

    let paths = if a.paths.is_empty() {
        vec![".".to_string()]
    } else {
        a.paths.clone()
    };

    for p in &paths {
        if p == "-" {
            // stdin
            let mut buf = String::new();
            if let Err(e) = io::stdin().read_to_string(&mut buf) {
                eprintln!("Error reading stdin: {}", e);
                return ExitCode::from(1);
            }
            return run_stdin(&a, "<stdin>", &buf, start);
        }
        let path = Path::new(p);
        if !path.exists() {
            eprintln!("Error: Failed to find markdown files: File not found: {}", p);
            return ExitCode::from(1);
        }
        collect_md_files(path, &mut files, &a);
    }

    // Dedup
    files.sort();
    files.dedup();

    let mut total_issues = 0u64;
    let mut fixable = 0u64;
    let mut files_with_issues = 0u64;
    let mut all_diagnostics: Vec<linter::Diagnostic> = Vec::new();

    for f in &files {
        let content = match fs::read_to_string(f) {
            Ok(s) => s,
            Err(_) => continue,
        };
        let mut diags = linter::lint(&content, &a);
        if !diags.is_empty() {
            files_with_issues += 1;
        }
        for d in &diags {
            if d.fixable {
                fixable += 1;
            }
            d.print(f, &a);
        }
        total_issues += diags.len() as u64;
        if a.fix && !diags.is_empty() {
            let fixed = linter::fix(&content, &a);
            if fixed != content {
                fs::write(f, fixed).ok();
            }
        }
        all_diagnostics.append(&mut diags);
    }

    let elapsed = start.elapsed();
    let ms = elapsed.as_millis();

    let output_format = a.output.as_deref().or(a.output_format.as_deref()).unwrap_or("text");

    if output_format == "json" {
        // Output JSON array
        println!("[]");
        return ExitCode::from(0);
    }

    let file_word = if files.len() == 1 { "file" } else { "files" };

    if total_issues == 0 {
        if !a.quiet {
            if files.len() == 1 {
                println!();
                println!("Success: No issues found in 1 file ({}ms)", ms);
            } else if files.len() > 1 {
                println!();
                println!("Success: No issues found in {} files ({}ms)", files.len(), ms);
            } else {
                println!("No markdown files found.");
            }
        }
        ExitCode::from(0)
    } else {
        if !a.quiet {
            println!();
            println!("Issues: Found {} issues in {} {} ({}ms)", total_issues, files_with_issues, file_word, ms);
            if fixable > 0 && !a.fix {
                println!("Run `rumdl fmt` to automatically fix {} of the {} issues", fixable, total_issues);
            }
        }
        match a.fail_on.as_deref().unwrap_or("any") {
            "never" => ExitCode::from(0),
            _ => ExitCode::from(1),
        }
    }
}

fn run_stdin(a: &CheckArgs, fname: &str, content: &str, start: std::time::Instant) -> ExitCode {
    let diags = linter::lint(content, a);
    let output_format = a.output.as_deref().or(a.output_format.as_deref()).unwrap_or("text");

    if a.fix {
        // Print fixed content
        let fixed = linter::fix(content, a);
        print!("{}", fixed);
        return ExitCode::from(0);
    }

    if output_format == "json" {
        println!("[]");
        return ExitCode::from(0);
    }

    if diags.is_empty() {
        if !a.quiet {
            println!("No issues found in {}", fname);
        }
        ExitCode::from(0)
    } else {
        for d in &diags {
            d.print(Path::new(fname), a);
        }
        ExitCode::from(1)
    }
}

fn collect_md_files(path: &Path, files: &mut Vec<PathBuf>, a: &CheckArgs) {
    if path.is_file() {
        if is_markdown_file(path) {
            files.push(path.to_path_buf());
        }
        return;
    }
    if path.is_dir() {
        let dir_name = path.file_name().and_then(|s| s.to_str()).unwrap_or("");
        // Default excludes
        let default_excludes: &[&str] = &[".git", ".github", "node_modules", "vendor", "dist", "build"];
        if !a.no_exclude && default_excludes.contains(&dir_name) {
            return;
        }
        // Check configured excludes  
        if !a.no_exclude {
            for ex in &a.exclude {
                if matches_glob(ex, dir_name) {
                    return;
                }
            }
        }
        let entries = match fs::read_dir(path) {
            Ok(e) => e,
            Err(_) => return,
        };
        for entry in entries.flatten() {
            collect_md_files(&entry.path(), files, a);
        }
    }
}

fn is_markdown_file(path: &Path) -> bool {
    match path.extension().and_then(|s| s.to_str()) {
        Some("md") | Some("markdown") | Some("mdx") | Some("mkd") | Some("mdown") => true,
        _ => false,
    }
}

fn matches_glob(pattern: &str, name: &str) -> bool {
    // Very basic glob; just do equality or simple wildcard
    if pattern == name {
        return true;
    }
    if pattern.contains("**/") {
        // strip it
        let p = pattern.replace("**/", "");
        return p == name;
    }
    false
}
