cat > src/main.rs <<'RUST_EOF'
// rumdl - minimal reimplementation focused on CLI surface

use std::env;
use std::process::ExitCode;

mod args;
mod commands;
mod embedded;
mod linter;
mod md;

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    match args::parse(&argv) {
        Ok(parsed) => commands::dispatch(parsed),
        Err(err) => {
            match err {
                args::ArgError::Help(text) => {
                    println!("{}", text);
                    ExitCode::from(0)
                }
                args::ArgError::Version => {
                    println!("rumdl 0.1.13");
                    ExitCode::from(0)
                }
                args::ArgError::Usage(msg) => {
                    if !msg.is_empty() {
                        eprintln!("{}", msg);
                    }
                    ExitCode::from(2)
                }
            }
        }
    }
}
RUST_EOF

